/// The pattern predicates still checked when a function is selected.
pub fn pattern_predicate<C: PatternContext>(_ctx: &C, id: u16) -> bool {
    match id {
        _ => unreachable!("pattern predicate {id} is not in this table"),
    }
}

/// The node predicates the table checks.
pub fn node_predicate<D: Dag, H: Hooks<D>>(dag: &D, hooks: &H, value: SDValue, id: u16) -> bool {
    let args = (dag, hooks, value);
    match id {
        0 => predicates::lane_idx_32(args),
        1 => predicates::memory_vt_i8(args),
        2 => predicates::memory_vt_i16(args),
        3 => predicates::memory_vt_i32(args),
        4 => predicates::unindexed_store(args),
        5 => predicates::non_truncating_store(args),
        6 => predicates::non_extending_load(args),
        7 => predicates::unindexed_load(args),
        9 => predicates::ext_load(args),
        11 => predicates::lane_idx_4(args),
        12 => predicates::lane_idx_2(args),
        14 => predicates::truncating_store(args),
        15 => predicates::lane_idx_8(args),
        17 => predicates::sext_load(args),
        18 => predicates::zext_load(args),
        20 => predicates::lane_idx_16(args),
        21 => predicates::memory_vt_f16(args),
        22 => predicates::memory_vt_v8i8(args),
        23 => predicates::memory_vt_v4i16(args),
        24 => predicates::memory_vt_v2i32(args),
        27 => predicates::add_nuw(args),
        28 => predicates::bool_node(args),
        29 => predicates::fp_imm_pos_zero(args),
        _ => unreachable!("node predicate {id} is not in this table"),
    }
}

